public class TimeSeries_createCopy_TriageGen2Test {

    private TimeSeries series;
    private RegularTimePeriod p1;
    private RegularTimePeriod p2;
    private RegularTimePeriod p3;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");

        // Create some time periods
        p1 = new Second(new Date(1000));
        p2 = new Second(new Date(2000));
        p3 = new Second(new Date(3000));

        series.add(p1, 1.0);
        series.add(p2, 2.0);
        series.add(p3, 3.0);
    }















    @Test
    public void testCreateCopyWithNonExistentPeriods() throws CloneNotSupportedException {
        // Period between p1 and p2
        RegularTimePeriod pMid = new Second(new Date(1500));
        // getIndex(p1) = 0
        // getIndex(pMid) -> -2. endIndex = -(-2 + 1) + 1 = 2.
        // This would call createCopy(0, 2) which is valid.

        // To trigger the emptyRange via the 'endIndex < startIndex' logic:
        // This is difficult because of the 'start.compareTo(end) > 0' check.
        // However, if the 'end' period is such that its calculated index is less than 'start' index:
        // If end is not in series, endIndex = -(getIndex(end)+1)+1.
        // If end is just before p1, getIndex(end) = -1. endIndex = -(-1+1)+1 = 1.
        // This logic seems to always result in a positive index.

        // Let's try to trigger the endIndex < 0 case.
        // The only way endIndex < 0 is if -(endIndex + 1) + 1 < 0 => -(endIndex+1) < -1 => endIndex+1 > 1 => endIndex > 0.
        // Actually, the code: endIndex = -(endIndex + 1); endIndex = endIndex + 1;
        // If getIndex is -1: endIndex = 0, then endIndex = 1.
        // If getIndex is -2: endIndex = 1, then endIndex = 2.

        // Let's verify the 'emptyRange' via the 'startIndex == this.data.size()' branch
        RegularTimePeriod pFar = new Second(new Date(5000));
        TimeSeries emptyCopy = series.createCopy(pFar, pFar);
        assertEquals(0, emptyCopy.getItemCount());
    }


}

